        bpf_map_update_elem(&policer_map, &src_ip, state, BPF_ANY);
        return XDP_DROP;
    }

    if (state->tokens < ip_total_len) {
        /* Insufficient tokens -> drop */
        bpf_map_update_elem(&policer_map, &src_ip, state, BPF_ANY);
        return XDP_DROP;
    }

    /* --- Token Deduction and Pass --- */
    state->tokens -= ip_total_len;
    bpf_map_update_elem(&policer_map, &src_ip, state, BPF_ANY);
    return XDP_PASS;
}

