	void *data = (void *)(long)ctx->data;
	void *data_end = (void *)(long)ctx->data_end;
	struct eth_hdr *eth;
	struct iphdr *ip;
	struct udphdr *udp;
	struct wg_header *wg;
	__u32 receiver_idx;
	struct wg_session_stat *stat;
	__u64 *last_seen;
	int eth_type;

