	if (ip->protocol != IPPROTO_UDP)
		return XDP_PASS;

	data += sizeof(*ip);
	if (data + sizeof(*udp) > data_end)
		return XDP_PASS;

	udp = data;

	/* 3. Verify UDP destination port is 51820 (WireGuard) */
	if (bpf_ntohs(udp->dest) != 51820)
		return XDP_PASS;

	data += sizeof(*udp);
	if (data + 4 > data_end)
		return XDP_PASS;

