	 *    Pop the outer 4-byte VLAN tag using adjust_head.
	 *    adjust_head moves the start pointer forward by 4 bytes,
	 *    effectively removing the outer VLAN tag from the visible frame. */
	if (bpf_xdp_adjust_head(ctx, 4) < 0)
		return XDP_PASS;

