    ip->ihl = 5;

    /* 8. Update ip->tot_len.
     *    tot_len represents the total length of the IP packet (header + payload).
     *    adjust_head reduced the payload size by 4 bytes, so we must subtract 4
     *    from tot_len to keep the length consistent. */
