    eth->h_source[5] = orig_eth->h_source[5];
    eth->h_dest[0] = orig_eth->h_dest[0];
    eth->h_dest[1] = orig_eth->h_dest[1];
    eth->h_dest[2] = orig_eth->h_dest[2];
    eth->h_dest[3] = orig_eth->h_dest[3];
