	/* Inner label: label=200, BOS=1 => value = (200 << 1) | 1 = 0x101 */
	*(uint32_t *)(ip - 1 + 4) = bpf_htonl((MPLS_INNER_LABEL << 1) | 1); /* BOS=1 */

