        return XDP_PASS;

    /* 3. Validate VLAN header fits within the frame */
    if (data + sizeof(*eth) + sizeof(*vlan) > data_end)
        return XDP_PASS;

    vlan = data + sizeof(*eth);

    /* 4. Extract 3-bit PCP from VLAN TCI field.
