            struct udphdr *udp = transport;
            hash ^= *(__u16 *)(&udp->source);
            hash ^= *(__u16 *)(&udp->dest);
        } else {
            struct tcphdr *tcp = transport;
            hash ^= *(__u16 *)(&tcp->source);
            hash ^= *(__u16 *)(&tcp->dest);
