        /* ICMP or other IP protocols: hash on IPs and protocol */
        hash ^= *(__u32 *)(data + sizeof(*eth) + 12);   /* src ip */
        hash ^= *(__u32 *)(data + sizeof(*eth) + 16);   /* dst ip */
        hash ^= (__u32)ip->protocol;
