    /* 4-way ECMP: redirect to ifindex 10, 11, 12, or 13 */
    hash = hash % 4;
    __u32 ifindex = 10 + hash;

    /* Redirect packet to selected next-hop */
    bpf_xdp_redirect_index(ctx, ifindex, 0);

    return XDP_PASS;
